import{_ as i,o as a,c as s,a5 as t}from"./chunks/framework.DGp912Ge.js";const h=JSON.parse('{"title":"User Responsibility Disclaimer","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/user-responsibility-disclaimer.md","filePath":"manual/safety/user-responsibility-disclaimer.md","lastUpdated":1785806273000}'),o={name:"manual/safety/user-responsibility-disclaimer.md"};function r(n,e,l,d,u,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="user-responsibility-disclaimer" tabindex="-1">User Responsibility Disclaimer <a class="header-anchor" href="#user-responsibility-disclaimer" aria-label="Permalink to &quot;User Responsibility Disclaimer&quot;">​</a></h1><p>Scope of responsibility and limitations when using the RBQ and related manuals and software.</p><div class="sb sb-required"><div class="sb-icon"><span class="sb-book" aria-hidden="true">📖</span></div><div class="sb-content"><p class="custom-block-title">REQUIRED READING</p><p>You must read the user manual and safety-related documentation. Review these documents in advance for legal and safety responsibility.</p></div></div><h2 id="intended-use-and-prohibited-use" tabindex="-1">Intended use and prohibited use <a class="header-anchor" href="#intended-use-and-prohibited-use" aria-label="Permalink to &quot;Intended use and prohibited use&quot;">​</a></h2><h3 id="intended-use" tabindex="-1">Intended use <a class="header-anchor" href="#intended-use" aria-label="Permalink to &quot;Intended use&quot;">​</a></h3><ul><li>The RBQ is a quadruped robot intended for <strong>transport and movement</strong> in <strong>industrial sites, restricted areas, and supervised environments</strong>.</li><li>Use is assumed in <strong>designated or marked areas</strong>. See <a href="/RBQ/manual/safety/operating-environment-requirements.html">Operating Environment Requirements</a> and <a href="/RBQ/manual/hardware/specification.html">Specifications</a> for motion and environment limits.</li><li>You may mount <strong>non-contact sensing and monitoring payloads</strong>; power can be supplied to such payloads.</li></ul><h3 id="unsuitable-use" tabindex="-1">Unsuitable use <a class="header-anchor" href="#unsuitable-use" aria-label="Permalink to &quot;Unsuitable use&quot;">​</a></h3><ul><li>The RBQ is <strong>not suitable for collaborative work</strong> where people and the robot share the same space continuously.</li><li>Use outside the intended scope without a risk assessment is prohibited.</li></ul><h3 id="explicit-prohibitions" tabindex="-1">Explicit prohibitions <a class="header-anchor" href="#explicit-prohibitions" aria-label="Permalink to &quot;Explicit prohibitions&quot;">​</a></h3><p>The following uses are prohibited (examples only; not exhaustive):</p><ul><li><strong>No riding</strong>: Carrying or transporting people or animals</li><li>Underwater or airborne use; weapon or medical device use; home use; transport of hazardous materials; intentional harm; illegal purposes; climbing assistance; tampering that impairs sensors or function, etc.</li></ul><p><strong>Low-level API control of joints</strong> is outside the intended use described in this document. If you use it that way, you need a <strong>separate risk assessment</strong>. See the <a href="/RBQ/software/developers-guide.html">Developer Guide</a> and API documentation.</p><h2 id="lawful-use" tabindex="-1">Lawful use <a class="header-anchor" href="#lawful-use" aria-label="Permalink to &quot;Lawful use&quot;">​</a></h2><ul><li>The user is responsible for complying with all applicable laws and regulations.</li><li>The product must be used only within the purposes, environments, and limits specified in the manual and by Rainbow Robotics. Rainbow Robotics is not liable for damage from use outside those limits.</li></ul><h2 id="safety-and-risk" tabindex="-1">Safety and risk <a class="header-anchor" href="#safety-and-risk" aria-label="Permalink to &quot;Safety and risk&quot;">​</a></h2><ul><li><strong>Risk assessment</strong>: The user or system integrator must perform a risk assessment for the actual environment (workplace, coexistence with people and equipment, etc.). Configure guards, devices, and procedures accordingly.</li><li><strong>Training</strong>: Anyone who operates, inspects, or maintains the system must complete the relevant manual and safety training before use.</li></ul><h2 id="modifications-and-unauthorized-repair" tabindex="-1">Modifications and unauthorized repair <a class="header-anchor" href="#modifications-and-unauthorized-repair" aria-label="Permalink to &quot;Modifications and unauthorized repair&quot;">​</a></h2><ul><li>If you modify the product or change parts or software without Rainbow Robotics approval, Rainbow Robotics is not liable for failures, accidents, or damage that result.</li><li>Repair and inspection should be within what the manual allows the user to do, or contact Rainbow Robotics. See <a href="/RBQ/manual/troubleshooting/error-reporting.html">Contact / Error Reporting</a>.</li></ul><h2 id="improper-use" tabindex="-1">Improper use <a class="header-anchor" href="#improper-use" aria-label="Permalink to &quot;Improper use&quot;">​</a></h2><ul><li>Improper use (explosive atmospheres, medical/life-related uses, transport of people or animals, no risk assessment, use beyond specifications, etc.) is prohibited. Rainbow Robotics is not liable for direct or indirect damage from such use.</li></ul><p>For legal or safety questions about product use, contact Rainbow Robotics. See <a href="/RBQ/manual/troubleshooting/error-reporting.html">Contact / Error Reporting</a>.</p>',21)])])}const m=i(o,[["render",r]]);export{h as __pageData,m as default};
